#!/usr/bin/env bash
# ============================================================================
# VideoMind - Landing proof panel: real wallet instead of sample signature
# ============================================================================
# Replaces the hardcoded 0x7a3f...9c4e sample on the landing page with a live
# wallet-aware panel: shows the connected wallet's real address, or the
# WalletButton (opens the wallet picker) when not connected.
# Reuses the existing WalletButton + useWallet - no new wallet logic.
#
# Apply AFTER Part 2 (the landing page must exist).
#
#   ./vm_landing_wallet.sh          apply
#   ./vm_landing_wallet.sh --revert restore from backup
# ============================================================================
set -euo pipefail
L="frontend/src/app/page.tsx"
WB="frontend/src/components/layout/WalletButton.tsx"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR="frontend/.vm_landingwallet_backups"
say() { printf '  %s\n' "$1"; }
die() { printf 'ERROR: %s\n' "$1" >&2; exit 1; }

[ -f "$L" ] || die "$L not found. Run from repo root (folder containing frontend/)."

if [ "${1:-}" = "--revert" ]; then
  [ -d "$BAKDIR" ] || die "No backup dir. Nothing to revert."
  LATEST="$(ls -1d $BAKDIR/*/ 2>/dev/null | sort | tail -1)"
  [ -n "$LATEST" ] || die "No backups found."
  cp "$LATEST/page.tsx" "$L"
  say "Reverted landing page from $LATEST"
  exit 0
fi

# preconditions
grep -q "actionable" "$L" 2>/dev/null || die "Landing page not found (Part 2 not applied?). Run ./vm_part2_landing.sh first."
[ -f "$WB" ] || die "WalletButton component missing at $WB - cannot wire wallet."
if grep -q "WalletButton" "$L" 2>/dev/null; then
  say "Already applied (landing uses WalletButton). Use --revert to undo."; exit 0
fi

mkdir -p "$BAKDIR/$STAMP"; cp "$L" "$BAKDIR/$STAMP/page.tsx"
say "Backup saved to $BAKDIR/$STAMP/"

TMP="$(mktemp)"; printf '%s' "" | base64 -d > "$TMP" || die "base64 decode failed."
grep -q "WalletButton" "$TMP" || die "payload verify failed (missing WalletButton). Nothing written."
grep -q "useWallet" "$TMP" || die "payload verify failed (missing useWallet). Nothing written."
grep -q "0x7a3f" "$TMP" && die "payload still has hardcoded address - aborting."
cp "$TMP" "$L"; rm -f "$TMP"

grep -q "WalletButton" "$L" || die "write verify failed - restore from $BAKDIR/$STAMP"
say "Applied: landing proof panel now shows the real connected wallet."
say "Next: cd frontend && npm run build"
